function waitForMenuAnimation(panel: HTMLElement, phase: 'animationstart' | 'animationend', name: string): Promise<boolean> {
  return new Promise(resolve => {
    const timer = setTimeout(() => finish(false), 1500);
    const listener = (event: Event) => {
      if ((event as AnimationEvent).animationName === name && event.target === panel) finish(true);
    };
    const finish = (observed: boolean) => {
      clearTimeout(timer);
      panel.removeEventListener(phase, listener);
      resolve(observed);
    };
    panel.addEventListener(phase, listener);
  });
}

async function waitForMenuRemoval(container: HTMLElement): Promise<boolean> {
  const end = performance.now() + 1500;
  while (container.querySelector('.mat-menu-panel') && performance.now() < end) {
    await new Promise(resolve => setTimeout(resolve, 20));
  }
  return !container.querySelector('.mat-menu-panel');
}

